@traced("relation.list")
def list_relations(workdir=None, material: str | None = None, input_quantity: str | None = None) -> dict:
    rels = registry.find(material=material, input_quantity=input_quantity)
    out = {"relations": [r.describe() for r in rels]}
    if not rels:
        out["note"] = "no relation matches the filter"
        out["known"] = [{"name": r.name, "material": r.material} for r in registry.all_relations()]
    return out


def apply_relation(name: str, inputs: dict | None = None, workdir=None) -> dict:
    try:
        rel = registry.get(name)
    except KeyError:
        return {"error": f"no relation named {name!r}", "known": [r.name for r in registry.all_relations()]}

    # The span is named after the relation (relation.<name>), so it is created per call rather than at import.
    @traced(f"relation.{name}")
    def _apply(**kw) -> dict:
        add_metadata(material=rel.material)
        return rel.apply(**kw).to_dict()

    out = _apply(**(inputs or {}))
    out["provenance"] = "inferred"
    return out


_HANDLERS = {
    "load_spectrum": load_spectrum,
    "fit_peaks": fit_peaks,
    "match_library": match_library,
    "classify_polarization": classify_polarization,
    "lookup_reference_modes": lookup_reference_modes,
    "list_relations": list_relations,
    "apply_relation": apply_relation,
}


def call(name: str, input: dict, workdir) -> str:
    """Run tool `name` with the model's input dict in `workdir` and return its JSON output as a string.

    Unknown tools raise KeyError; library errors propagate, and the runner reports them to the model as tool
    errors. Inputs the model can correct (unknown material or relation) come back as JSON with an `error` key.
    """
    if name not in _HANDLERS:
        raise KeyError(f"unknown tool {name!r}; available: {', '.join(_HANDLERS)}")
    result = _HANDLERS[name](workdir=workdir, **(input or {}))
    return json.dumps(result, default=str)

"""Ingest papers into the library and read their figures back.

The parse-once rule lives here: ``ingest`` returns the stored parse when the paper is already in the
library with the current parser version, and only otherwise downloads and parses it.

Input: an arXiv id, optionally the paper's Bond record (title, DOI, licence) for ``meta.json``.
Process: store lookup -> ``arxiv.fetch_pdf`` -> ``pdf.parse_pdf`` (Docling) -> figure records ->
``Store.record_parse``. Synchronous and slow on a cold parse; the server runs it in a worker thread.
Output: dicts with an explicit ``status`` (``ok``, ``cached``, ``fetch_failed``, ``parse_failed``,
``not_found``) so the agent reasons about a gap instead of catching an exception.
"""
from __future__ import annotations

import re
from pathlib import Path
from typing import Optional

from . import config
from .arxiv import bare_id, fetch_pdf
from .figures import figures_from_tree
from .pdf.schema import from_json
from .store import Store


def _parser_version() -> str:
    # imported lazily: the pipeline module pulls in the Docling adapter
    from .pdf.pipeline import PARSER_VERSION

    return PARSER_VERSION


def figure_dicts(tree_path: Path) -> list[dict]:
    """Figure records from a stored ``tree.json``, with paths relative to its folder."""
    doc_dir = tree_path.parent
    root = from_json(tree_path.read_text(encoding="utf-8"))
    out = []
    for f in figures_from_tree(root, doc_dir):
        rel = f.image_path.relative_to(doc_dir).as_posix() if f.image_path else None
        out.append({
            # no invented label: crop file numbers are extraction order, not printed figure numbers
            # (Lee 2010 has Figs. 1-4 plus an uncaptioned TOC graphic, cropped as fig5.png)
            "label": f.label,
            "image_ref": f"image {_stem_number(rel)}" if rel else None,
            "caption": f.caption,
            "page": f.page,
            "image_rel": rel,
            "image_path": str(f.image_path) if f.image_path else None,
            "mentions": f.mentions,
            "node_id": f.node_id,
        })
    return out


def _stem_number(rel: Optional[str]) -> Optional[str]:
    m = re.search(r"fig(?:ure)?[._-]?(\d+)", rel or "", re.I)
    return m.group(1) if m else None


def _figure_number(text: Optional[str]) -> Optional[str]:
    """"Figure 2", "FIG. 2", "Fig 2b", "2" -> "2"."""
    m = re.search(r"(\d+)", text or "")
    return m.group(1) if m else None


def find_figure(figures: list[dict], which: str) -> Optional[dict]:
    """Match a figure by its printed number ("2", "Fig. 2", "Figure 2"), its ``image_ref``
    ("image 5", for images without a caption) or its node id."""
    for f in figures:
        if which.strip().lower() in (f.get("node_id"), (f.get("image_ref") or "").lower()):
            return f
    if which.strip().lower().startswith("image"):
        return None
    want = _figure_number(which)
    if want is None:
        return None
    for f in figures:
        if _figure_number(f.get("label")) == want:
            return f
    return None


def meta_from_bond(p: dict) -> dict:
    """The fields of a Bond paper record worth keeping in ``meta.json``."""
    first = (p.get("dates") or {}).get("first_available") or {}
    year = (first.get("value") or p.get("first_submitted") or "")[:4]
    return {
        "doi": p.get("doi") or None,
        "title": p.get("title"),
        "authors": p.get("authors") or [],
        "year": int(year) if year.isdigit() else None,
        "license": p.get("license"),
        "url": p.get("url"),
        "journal_ref": p.get("journal_ref"),
        "citation_count": p.get("citation_count"),
    }


def ingest(store: Store, arxiv_id: str, *, meta: Optional[dict] = None, force: bool = False) -> dict:
    """Return the paper's parse from the library, parsing it first if needed."""
    base_id = bare_id(arxiv_id)
    row = store.lookup(base_id=base_id)
    if row and not force and row["status"] == "parsed" and row["parser_version"] == _parser_version():
        tree = store.tree_path(row)
        if tree:
            return {"status": "cached", "paper": row, "tree_path": str(tree)}

    meta = meta or {}
    pdf = fetch_pdf(base_id, store.paper_dir(base_id) / "paper.pdf")
    if pdf is None:
        store.record_failure(base_id, "fetch_failed", meta)
        return {"status": "fetch_failed", "base_id": base_id,
                "detail": f"could not download https://arxiv.org/pdf/{base_id}"}

    from .pdf import parse_pdf

    try:
        root = parse_pdf(pdf, store.parsed_dir(base_id), device=config.parse_device(), force=force)
    except ImportError:
        return {"status": "parse_failed", "base_id": base_id,
                "detail": "Docling is not installed: pip install iopic-bond[parse]"}
    except Exception as exc:  # Docling failures are varied; record and report, never crash the server
        store.record_failure(base_id, "parse_failed", meta)
        return {"status": "parse_failed", "base_id": base_id, "detail": f"{type(exc).__name__}: {exc}"}

    tree = store.parsed_dir(base_id) / root.id / "tree.json"
    row = store.record_parse(base_id, meta, root.id, _parser_version(), figure_dicts(tree))
    return {"status": "ok", "paper": row, "tree_path": str(tree)}


def outline(tree_path: Path, max_sections: int = 40) -> list[str]:
    """Section headings of a parsed paper, in reading order."""
    root = from_json(Path(tree_path).read_text(encoding="utf-8"))
    heads = []
    for n in root.walk():
        if n.type in ("section", "subsection", "chapter") and n.text:
            heads.append(n.text.strip()[:120])
    return heads[:max_sections]

"""Settings for iopic-Bond: where the library lives, the Bond token, the parse device.

Input: environment variables, optionally from a ``.env`` file (``IOPIC_BOND_ENV_FILE``, else the
nearest ``.env`` from the working directory upward).
Process: resolves each setting with a documented default.
Output: plain functions read by the store, the Bond client and the CLI.

    IOPIC_BOND_HOME      library root (default: the OS cache dir from platformdirs)
    VALENCY_BOND_TOKEN   Valency Direct API token from https://app.valency.io/settings
    VALENCY_BOND_URL     Bond endpoint (default https://mcp.valency.io/)
    IOPIC_BOND_DEVICE    Docling device, "cpu" or "cuda" (default cpu)
"""
from __future__ import annotations

import os
from pathlib import Path

DEFAULT_BOND_URL = "https://mcp.valency.io/"


def load_env() -> None:
    """Load ``.env`` into the process environment without overriding variables already set."""
    from dotenv import find_dotenv, load_dotenv

    path = os.environ.get("IOPIC_BOND_ENV_FILE") or find_dotenv(usecwd=True)
    if path:
        load_dotenv(path, override=False)


def home() -> Path:
    env = os.environ.get("IOPIC_BOND_HOME")
    if env:
        root = Path(env).expanduser()
    else:
        from platformdirs import user_cache_path

        # appauthor=False: no extra vendor folder level on Windows
        root = user_cache_path("iopic-bond", appauthor=False)
    root.mkdir(parents=True, exist_ok=True)
    return root.resolve()


def bond_token() -> str | None:
    return os.environ.get("VALENCY_BOND_TOKEN") or None


def bond_url() -> str:
    return os.environ.get("VALENCY_BOND_URL", DEFAULT_BOND_URL)


def parse_device() -> str:
    return os.environ.get("IOPIC_BOND_DEVICE", "cpu")

def folder_name(base_id: str) -> str:
    """Old-style ids contain a slash (``cond-mat/0501234``), which cannot be a folder name."""
    return base_id.replace("/", "_")


class Store:
    def __init__(self, root: Optional[Path] = None):
        self.root = Path(root) if root else config.home()
        self.papers_dir = self.root / "papers"
        self.papers_dir.mkdir(parents=True, exist_ok=True)
        self.db = sqlite3.connect(self.root / "index.sqlite", check_same_thread=False)
        self.db.row_factory = sqlite3.Row
        self.db.executescript(_SCHEMA)

    # -- paths ---------------------------------------------------------------------------------

    def paper_dir(self, base_id: str) -> Path:
        return self.papers_dir / folder_name(base_id)

    def parsed_dir(self, base_id: str) -> Path:
        return self.paper_dir(base_id) / "parsed"

    def tree_path(self, row: dict) -> Optional[Path]:
        if not row.get("content_hash"):
            return None
        p = self.parsed_dir(row["base_id"]) / row["content_hash"] / "tree.json"
        return p if p.exists() else None

    # -- lookup --------------------------------------------------------------------------------

    def lookup(self, *, base_id: Optional[str] = None, doi: Optional[str] = None) -> Optional[dict]:
        """Find a paper by DOI first (shared by the arXiv and journal records), then by arXiv id."""
        if doi:
            r = self.db.execute("SELECT * FROM papers WHERE lower(doi) = lower(?)", (doi.strip(),)).fetchone()
            if r:
                return dict(r)
        if base_id:
            r = self.db.execute("SELECT * FROM papers WHERE base_id = ?", (base_id,)).fetchone()
            if r:
                return dict(r)
        return None

    def known_ids(self, papers: list[dict]) -> set[str]:
        """Base ids among ``papers`` (Bond records) that are already parsed in the library."""
        out = set()

